#!/usr/bin/env bash
# 在 AMD 开发者平台的实例里，取回本次提交的文件并跑 V5 / 候选对照。
# 先试多个可访问的源，全部失败时用内置的 base64 兜底。
set -Eeuo pipefail
WORK=${1:-/workspace/amd-ab}
BASE_MIRRORS=(
  "https://cdn.jsdelivr.net/gh/ieuies/seekdb@amd-hipvs-v5"
  "https://raw.githubusercontent.com/ieuies/seekdb/amd-hipvs-v5"
  "https://ghproxy.net/https://raw.githubusercontent.com/ieuies/seekdb/amd-hipvs-v5"
  "https://gh-proxy.com/https://raw.githubusercontent.com/ieuies/seekdb/amd-hipvs-v5"
  "https://mirror.ghproxy.com/https://raw.githubusercontent.com/ieuies/seekdb/amd-hipvs-v5"
)

mkdir -p "$WORK/files"
cd "$WORK/files"

fetch() {
  local name; name=$(basename "$1")
  for m in "${BASE_MIRRORS[@]}"; do
    if curl -fsSL --max-time 45 "$m/$1" -o "$name" 2>/dev/null && [ -s "$name" ]; then
      echo "  取到 $name  <- $m"; return 0
    fi
  done
  return 1
}

echo "=== 抓取文件 ==="
ok=1
for p in "tools/hipvs_bridge/seekdb_cuvs_bridge.c" "tools/hipvs_bridge/bridge_v5.c" "tools/hipvs_bridge/bench_bridge.py" "tools/hipvs_bridge/run_amd_ab.sh"; do
  fetch "$p" || { echo "  !! 抓不到 $p"; ok=0; }
done

if [ "$ok" -ne 1 ]; then
  echo "=== 源都不可用，用内置 base64 兜底 ==="
  cat > /tmp/seekdb_cuvs_bridge.c.b64 <<'B64EOF'

B64EOF
  cat > /tmp/bridge_v5.c.b64 <<'B64EOF'

B64EOF
  cat > /tmp/bench_bridge.py.b64 <<'B64EOF'

B64EOF
  cat > /tmp/run_amd_ab.sh.b64 <<'B64EOF'

B64EOF
  base64 -d /tmp/seekdb_cuvs_bridge.c.b64 > seekdb_cuvs_bridge.c
  base64 -d /tmp/bridge_v5.c.b64        > bridge_v5.c
  base64 -d /tmp/bench_bridge.py.b64    > bench_bridge.py
  base64 -d /tmp/run_amd_ab.sh.b64      > run_amd_ab.sh
  chmod +x run_amd_ab.sh
fi

ls -la

echo
echo "=== 落位到 seekdb 源码树 ==="
SRC_DIR=${SRC_DIR:-$(pwd)}
while [ "$SRC_DIR" != "/" ] && [ ! -f "$SRC_DIR/tools/hipvs_bridge/seekdb_cuvs_bridge.c" ]; do
  SRC_DIR=$(dirname "$SRC_DIR")
done
if [ ! -f "$SRC_DIR/tools/hipvs_bridge/seekdb_cuvs_bridge.c" ]; then
  echo "找不到 seekdb 源码树，用 SRC_DIR 指定" >&2
  exit 3
fi
echo "源码树: $SRC_DIR"
cp seekdb_cuvs_bridge.c "$SRC_DIR/tools/hipvs_bridge/seekdb_cuvs_bridge.c"
cp bench_bridge.py        "$SRC_DIR/tools/hipvs_bridge/bench_bridge.py"
cp run_amd_ab.sh          "$SRC_DIR/tools/hipvs_bridge/run_amd_ab.sh"
cp bridge_v5.c            "$WORK/bridge_v5.c"
chmod +x                 "$SRC_DIR/tools/hipvs_bridge/run_amd_ab.sh"

echo
echo "=== 找 observer 与它的 bridge ==="
find / -maxdepth 7 -type f -name seekdb -perm -u+x 2>/dev/null | head -5
echo "（上面是候选的 observer 路径，用 SEEKDB_BIN 指定最合适的一个）"

echo
echo "=== 开始 A/B ==="
cd "$SRC_DIR"
if [ "${SMOKE:-1}" = "1" ]; then
  ROWS=${ROWS:-50000} QUERIES=${QUERIES:-1024} bash tools/hipvs_bridge/run_amd_ab.sh "$WORK/smoke"
  echo
  echo "冒烟通过。全量：SMOKE=0 ROWS=250000 DIM=128 QUERIES=4096 bash tools/hipvs_bridge/run_amd_ab.sh $WORK/full"
else
  ROWS=${ROWS:-250000} DIM=${DIM:-128} QUERIES=${QUERIES:-4096} bash tools/hipvs_bridge/run_amd_ab.sh "$WORK/full"
fi
